SELECT id, customer_id, device, browser, started_at, country, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, LAST_VALUE(country, TRUE) OVER (PARTITION BY customer_id, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country FROM sessions
